# 58_rd_cap_sensitivity.R  Sensitivity only (Aaron, November 18, 2026): the system of script 51 with stand relative density held at or below 1.0.
# Nothing is deployed from this script. Rule, written before the run: at the end of each annual step (after growth, mortality and ingrowth), if the
# stand density index exceeds SDImax, every record's expansion factor is multiplied by SDImax / SDI, so the stand returns to RD = 1 with deaths
# spread in proportion to stems (no size preference). Compared with the published system on (a) the six scenarios, point and 90% bands from paired
# draws (same seed, same random numbers), (b) the benchmark with SDImax out of fold, and (c) the six 200-year gates. No fitting.
L <- readLines("~/jobs/koa_final_eq_20261110/scripts/51_j1_items.R"); Sys.setenv(KOA_CORES = "3"); eval(parse(text = L[1:55])); dir.create("out", showWarnings = FALSE)
simc <- function(dbh, ht, ex, byi, pl, years, sm, bg. = bg, bm. = bm, R = 1, sig = 0, dl = 0, ph = 1, ing = NULL, cap = TRUE) { out <- matrix(NA_real_, years + 1, 8, dimnames = list(NULL, c("BA", "TPH", "QMD", "HT", "VOL", "RD", "SDI", "CUT")))
  for (y in 0:years) { s <- koa_stand(dbh, ht, ex); out[y + 1, 1:7] <- c(s$BA, s$TPH, s$QMD, s$HT, 0.40 * s$BA * s$HT, s$SDI / sm, s$SDI); if (y == 0) out[1, 8] <- 0; if (y == years) break
    bal <- koa_bal(dbh, s$ba); rd <- s$SDI / sm; g <- as.numeric(exp(xm(dbh, bal, s$BA, s$SDI, sm, byi, pl) %*% bg.)) * R; if (sig > 0) { s2 <- log(1 + (sig * pmax(g, 0.01)^(dl - 1))^2); g <- g * exp(rnorm(length(g), 0, sqrt(s2)) - s2 / 2) }
    pm <- 1 - exp(-ph * exp(as.numeric(cbind(1, log(dbh + 1), dbh, dbh^2, bal, log(max(rd, 0.001)), log(byi), pl) %*% bm.))); ht <- ht + hB2(ht, bal / max(s$BA, 1e-6) * rd, log(byi), pl); dbh <- dbh + g; ex <- ex * (1 - pm); if (!is.null(ing)) { ni <- ing(s$QMD); if (is.finite(ni) && ni > 0) { dbh <- c(dbh, 12.7); ht <- c(ht, kh3(12.7, byi)); ex <- c(ex, ni) } }
    cut <- 0; if (cap) { z <- koa_stand(dbh, ht, ex); if (z$SDI > sm) { cut <- z$TPH * (1 - sm / z$SDI); ex <- ex * sm / z$SDI } }; out[y + 2, 8] <- cut }
  out }
# check: with cap = FALSE simc reproduces simx
L0 <- getL(1); stopifnot(max(abs(simc(L0$DBH, L0$HT, L0$EXPF_c, SC$byi[5], 1, 100, SC$sdimax[5], cap = FALSE)[, 1:7] - simx(L0$DBH, L0$HT, L0$EXPF_c, SC$byi[5], 1, 100, SC$sdimax[5]))) < 1e-10); cat("simc(cap = FALSE) reproduces simx\n")
# (a) scenarios: point and paired draws
VARS <- c("BA", "TPH", "QMD", "HT", "VOL", "RD"); YR <- c(20, 40, 100)
RES <- rbindlist(parallel::mclapply(seq_len(nrow(SC)), function(i) { Lx <- getL(SC$planted[i]); pl <- SC$planted[i]; byi <- SC$byi[i]
  pt <- lapply(c(FALSE, TRUE), function(cp) simc(Lx$DBH, Lx$HT, Lx$EXPF_c, byi, pl, 100, SC$sdimax[i], ing = IG(pl), cap = cp))
  dr <- lapply(c(FALSE, TRUE), function(cp) simplify2array(lapply(seq_len(ND), function(k) { set.seed(580000 + 1000 * i + k); q <- draw(log(byi), pl, FALSE); ig <- if (pl == 0) IGd() else NULL; simc(Lx$DBH, Lx$HT, Lx$EXPF_c, byi, pl, 100, q$sm, q$bg, q$bm, q$R, FT$sigma, FT$delta, q$ph, ing = ig, cap = cp) })))
  rbindlist(lapply(1:2, function(j) rbindlist(lapply(c(VARS, "CUT"), function(v) { a <- dr[[j]][, v, ]; data.table(planted = pl, level = SC$level[i], byi = byi, sdimax = SC$sdimax[i], capped = j == 2, var = v, year = 0:100, point = pt[[j]][, v], p05 = apply(a, 1, quantile, 0.05, na.rm = TRUE), p50 = apply(a, 1, quantile, 0.5, na.rm = TRUE), p95 = apply(a, 1, quantile, 0.95, na.rm = TRUE), share_binding = if (v == "CUT") rowMeans(a > 0, na.rm = TRUE) else NA_real_) })))) }, mc.cores = 3))
fwrite(RES, "out/rd_cap_scenarios_58.csv"); f1 <- function(p, l, h, d) sprintf(paste0("%.", d, "f (%.", d, "f to %.", d, "f)"), p, l, h)
T <- RES[year %in% YR & var %in% c("BA", "QMD", "TPH", "RD")]; T[, cell := f1(point, p05, p95, ifelse(var == "RD", 2, ifelse(var == "TPH", 0, 1)))]; W <- dcast(T, planted + level + year + var ~ capped, value.var = "cell"); setnames(W, c("FALSE", "TRUE"), c("published", "RD_capped")); W[, level := factor(level, c("lo", "md", "hi"))]; setorder(W, planted, level, year, var)
cat("\n(a) scenarios at 20, 40 and 100 years: point (90% band,", ND, "paired draws)\n"); print(W, nrow = 200); fwrite(W, "out/rd_cap_table_58.csv")
D <- dcast(RES[var %in% c("BA", "QMD", "TPH") & year %in% YR], planted + level + year + var ~ capped, value.var = "point"); D[, pct := round(100 * (`TRUE` / `FALSE` - 1), 1)]; cat("\npercent change of the point value under the cap\n"); print(dcast(D, planted + level + year ~ var, value.var = "pct"))
CT <- RES[var == "CUT" & capped == TRUE, .(years_binding_point = sum(point > 0), first_year = if (any(point > 0)) min(year[point > 0]) else NA_integer_, last_year = if (any(point > 0)) max(year[point > 0]) else NA_integer_, stems_removed_point = round(sum(point), 1), mean_share_draws_binding = round(mean(share_binding[year >= 1]), 3)), by = .(planted, level)]
cat("\nwhen the cap binds (point run, 100 years) and the mean share of draws in which it binds in a year\n"); print(CT); cat("largest RD: published", RES[var == "RD" & capped == FALSE, round(max(point), 3)], " capped", RES[var == "RD" & capped == TRUE, round(max(point), 3)], "; largest 95th percentile: published", RES[var == "RD" & capped == FALSE, round(max(p95), 3)], " capped", RES[var == "RD" & capped == TRUE, round(max(p95), 3)], "\n")
# (b) benchmark with the cap, SDImax out of fold
benc <- rbindlist(lapply(PI, function(x) { z <- simc(x$L$DBH, x$L$HT, x$L$EXPF_c, x$byi, x$pl, max(x$obs$h), SMO[[x$p]]); cbind(pid = x$p, planted = x$pl, x$obs, p_surv = z[x$obs$h + 1, "TPH"] / x$N0, p_qmd = z[x$obs$h + 1, "QMD"], p_ba = z[x$obs$h + 1, "BA"], bind = sum(z[, "CUT"] > 0, na.rm = TRUE)) }))
cat("\n(b) benchmark, published\n"); print(cbind(set = "all", sm1(bench))); print(bench[, sm1(.SD), by = planted]); cat("benchmark, RD capped\n"); print(cbind(set = "all", sm1(benc))); print(benc[, sm1(.SD), by = planted]); cat("benchmark plots on which the cap binds in any year:", benc[, max(bind), by = pid][V1 > 0, .N], "of", uniqueN(benc$pid), "\n")
lastc <- benc[, .SD[which.max(h)], by = pid]; cat("equivalence at each plot's longest horizon, RD capped\n"); print(rbindlist(lapply(list(all = lastc, planted = lastc[planted == 1], natural = lastc[planted == 0]), function(x) rbind(cbind(var = "survival", equiv_boot(x$o_surv, x$p_surv, x$pid)[, ..cols]), cbind(var = "QMD", equiv_boot(x$o_qmd, x$p_qmd, x$pid)[, ..cols]), cbind(var = "BA", equiv_boot(x$o_ba, x$p_ba, x$pid)[, ..cols]))), idcol = "set"))
# (c) gates with the cap: the gate code of script 51 run with simx replaced by the capped function
gates0 <- { eval(parse(text = L[56:59])); gates }; simx <- function(...) simc(...)[, 1:7]; eval(parse(text = L[55:59])); cat("\n(c) gates, published\n"); print(gates0); cat("gates, RD capped\n"); print(gates)
print(S[year %in% c(20, 40, 100, 200), .(planted, level, year, BA = round(BA, 1), TPH = round(TPH), QMD = round(QMD, 1), RD = round(RD, 2))]); cat("\n58 done\n")
